FILES = {"t3/research/common.py": "", "t3/research/exp_lgb_hurdle.py": "", "t3/research/exp_cbq.py": "", "t3/research/avg_q.py": ""}
PATCH = []

import os, glob, base64, subprocess, sys, time, shutil
W = "/kaggle/working/repo"; T0 = time.time()
for p, b in FILES.items():
    f = os.path.join(W, p); os.makedirs(os.path.dirname(f), exist_ok=True); open(f, "wb").write(base64.b64decode(b))
tr = glob.glob("/kaggle/input/**/01_binary_classification/train.csv", recursive=True)
assert tr, "competition data not found"
os.makedirs(W + "/t3/research/oof", exist_ok=True)   # exp_lgb_hurdle saves p only if oof/ already exists
root = os.path.dirname(os.path.dirname(tr[0])); print("data root", root, os.listdir(root))
LINKS = ["/kaggle/working/cpe342-kaggle-main", W + "/cpe342-kaggle-main"]   # t1 common: ROOT/../../../ ; t3 common: cwd-relative
for l in LINKS:
    if not os.path.exists(l): os.symlink(root, l)
for p, s in PATCH:
    f = os.path.join(W, p); t = open(f).read(); assert s[0] in t, (p, s[0]); open(f, "w").write(t.replace(s[0], s[1]))
def run(*cmd, env=None):
    e = dict(os.environ, **(env or {})); print(">>", " ".join(cmd), env or "", f"[{(time.time()-T0)/3600:.2f} h]", flush=True)
    subprocess.run([sys.executable, *cmd], cwd=W, env=e, check=True)
run("t3/research/exp_lgb_hurdle.py", "lgbh_log")
run("t3/research/exp_lgb_hurdle.py", "clf_s1", "--clf_only", "--seed", "1")
run("t3/research/exp_lgb_hurdle.py", "clf_s2", "--clf_only", "--seed", "2")
run("t3/research/exp_lgb_hurdle.py", "clf_s3", "--clf_only", "--seed", "3")
run("t3/research/exp_lgb_hurdle.py", "clf_s4", "--clf_only", "--seed", "4")
run("t3/research/exp_lgb_hurdle.py", "clf_s5", "--clf_only", "--seed", "5")
run("t3/research/exp_lgb_hurdle.py", "clf_s6", "--clf_only", "--seed", "6")
run("t3/research/exp_lgb_hurdle.py", "clf_s7", "--clf_only", "--seed", "7")
run("t3/research/exp_lgb_hurdle.py", "clf_s8", "--clf_only", "--seed", "8")
run("t3/research/exp_lgb_hurdle.py", "clf_s9", "--clf_only", "--seed", "9")
run("t3/research/exp_cbq.py", "cbq_d4", "--depth", "4", "--lr", "0.05")
run("t3/research/exp_cbq.py", "cbq_d4s1", "--depth", "4", "--lr", "0.05", "--seed", "1")
run("t3/research/exp_cbq.py", "cbq_d4s2", "--depth", "4", "--lr", "0.05", "--seed", "2")
run("t3/research/exp_cbq.py", "cbq_d4s3", "--depth", "4", "--lr", "0.05", "--seed", "3")
run("t3/research/exp_cbq.py", "cbq_d4s4", "--depth", "4", "--lr", "0.05", "--seed", "4")
run("t3/research/exp_cbq.py", "cbq_d4s5", "--depth", "4", "--lr", "0.05", "--seed", "5")
run("t3/research/exp_cbq.py", "cbq_d4s6", "--depth", "4", "--lr", "0.05", "--seed", "6")
run("t3/research/exp_cbq.py", "cbq_d4s7", "--depth", "4", "--lr", "0.05", "--seed", "7")
run("t3/research/exp_cbq.py", "cbq_d4s8", "--depth", "4", "--lr", "0.05", "--seed", "8")
run("t3/research/exp_cbq.py", "cbq_d4s9", "--depth", "4", "--lr", "0.05", "--seed", "9")
run("t3/research/avg_q.py", "bag_q3p3", "--q", "cbq_d4,cbq_d4s1,cbq_d4s2", "--p", "lgbh_log,clf_s1,clf_s2")
run("t3/research/avg_q.py", "bag_q10p3", "--q", "cbq_d4,cbq_d4s1,cbq_d4s2,cbq_d4s3,cbq_d4s4,cbq_d4s5,cbq_d4s6,cbq_d4s7,cbq_d4s8,cbq_d4s9", "--p", "lgbh_log,clf_s1,clf_s2")
run("t3/research/avg_q.py", "bag_q3p10", "--q", "cbq_d4,cbq_d4s1,cbq_d4s2", "--p", "lgbh_log,clf_s1,clf_s2,clf_s3,clf_s4,clf_s5,clf_s6,clf_s7,clf_s8,clf_s9")
run("t3/research/avg_q.py", "bag_q10p10", "--q", "cbq_d4,cbq_d4s1,cbq_d4s2,cbq_d4s3,cbq_d4s4,cbq_d4s5,cbq_d4s6,cbq_d4s7,cbq_d4s8,cbq_d4s9", "--p", "lgbh_log,clf_s1,clf_s2,clf_s3,clf_s4,clf_s5,clf_s6,clf_s7,clf_s8,clf_s9")

for l in LINKS:
    if os.path.islink(l): os.unlink(l)
for c in glob.glob(W + "/**/cache", recursive=True): shutil.rmtree(c, ignore_errors=True)
print("DONE", f"{(time.time()-T0)/3600:.2f} h")
